import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/letter/2024/one-is-all.html","title":"One is All","lang":"zh-CN","frontmatter":{"title":"One is All","date":"2024-01-21T18:32:50.000Z","author":"AI悦创","isOriginal":true,"icon":"letter","sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1705834203000,"updatedTime":1748181844000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":18,"url":"https://github.com/AndersonHJB"}],"changelog":[{"hash":"c3b1f109dc15a971c7a53e56ed98bcdafe58cfad","time":1748181844000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完善文档：移除重要性文档中的多余空行以提升格式整洁性"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"0a2c3359e6761d9dbba537027a8f5252002d0893","time":1706632057000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"decodeColumnShuffleCipher(encodedMessage) [20 pts] Write the function decodeColumnShuffleCipher, which takes an encoding from encodeColumnShuffleCipher and runs it in reverse, returning the plaintext that generated the encoding. For example, decodeColumnShuffleCipher(\\"1320TKA-WTAWACD-EATN\\") returns \\"WEATTACKATDAWN\\"."},{"hash":"c71fb787f9176d9f2a9b15b3bd6a68265bac004d","time":1706625999000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"其实上次跟你说，跟你见面后我不想相亲了，这句话真不是夸张，有时候缘分就是这么奇妙，看到自己注定的那个人，可能那一眼就认定了。因为我也是个感性的人，我一直坚持的原因：我想跟我喜欢的人在一起，我不想将就，所以我未来的世界不想失去，我想陪伴你生活，和你去一起看世界美好的东西"},{"hash":"9769cea7432d4809a5c8f99c2c49b5d7e380e481","time":1705935068000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"2024-01-22 22:50:51"},{"hash":"501a939b7387dc43aeb17f1a60127883d6f133af","time":1705865071000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"kjz"},{"hash":"c971cc52be04bf880db1beda6d0fba69ac4fd799","time":1705862987000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"我觉得尽管我们是相亲认识的，但是我觉得那又怎么样，在茫茫人海里遇见你也是一种缘分，尽管相亲认识的很少有互相喜欢的，都是条件碰条件。但是我觉得我对你的感情也好、条件也好。我都能真诚，认真的对待你 ，在跟你那天见完面后，我就觉得：你永远是我的 Plan A。"},{"hash":"a5b1c7d5b27b441e4525524f70b14d6d83f2f457","time":1705862647000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"康佳珍的信"},{"hash":"11d064867a7b5043c0c255fdf5c23ed9adb3dad0","time":1705849295000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"letter"},{"hash":"a68716d5b7d21598c80936d0586600461a1a9f1f","time":1705838939000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"dc92d62fb35ab6e18b9c92dccba4af443dfca0a0","time":1705838512000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"/letter/2024/one-is-all"},{"hash":"0cb3598e09191593ebf7f17a8eaf8ddcb315d5af","time":1705837575000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"letter"},{"hash":"e1f4f525761fb1b6817a0a44eddd6deed9f5aa57","time":1705836474000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"letter03"},{"hash":"d290c126e6ea56df90948295b95f0880dd3a87e3","time":1705835991000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"27年，我从未知道失眠是什么，也不知道人为什么会失眠。从某一个中午，我遇见了一人。我半夜突然醒来，但不论如何都睡不着，大脑异常的清醒。原来，我失眠了。"},{"hash":"90047e6a51ebd281b527225e7c4131d4a7995e9f","time":1705835799000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"letter03"},{"hash":"e60f9a397f6173ae1c259d07bb0c9c2c44be8cc8","time":1705834797000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"letter02"},{"hash":"b4eca6e3a51ff1d0f1ca6aa4eefe9a1da4395dec","time":1705834203000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"01"}]},"readingTime":{"minutes":9.65,"words":2894},"filePathRelative":"letter/2024/one-is-all.md"}`),a={name:`one-is-all.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<div style="text-align:center;"><p>相思本是无凭语，莫向花笺费泪行。</p></div><div style="text-align:right;"><p>2024-01-21 18:32:50 家</p></div><hr><p>亲爱的康佳珍你好，</p><p>给你写这封信此前，想了非常多。但我知道，我必须摆脱自我感动以最理智、最真诚的心写下这信。这封信，我写了许久，反复斟酌以免给你带来压力或者其它，但又需要表达清楚。</p><p>我这十几天一直很不平静。</p><p>因为，我遇到了一个非常需要我全身心且谨慎、小心翼翼、尊重的一个女生。</p><p>她让我心动，也让我“度日如年”，时刻等待着另一端回信。</p><p>她很懂礼貌，是唯一一个会把人送到门口的，也是我唯一在走出时，不停回头去看。</p><p>她和我见面时，同我一样紧张。我想看着她脸对话，但紧张使我不敢看太久。</p><p>她的每一次回复，我都非常开心，就像一个小孩收到了一件珍贵的礼物似的。导致，我无法抑制的发了很长很长的小作文。</p><p>她有点冷漠，我需要不停的找话题，不停的想跟她互相了解。<s>大家都</s>或许理性的大脑早已告诉我说：放弃吧、不用找话题顺其自然就行。</p><p>我的能力与经历，很少有人或事让我如此卑微或舔<s>，何故如此卑微</s>。但我和沈从文想法一致：在心爱的人面前，卑微算什么呢？</p><p>我总觉得真诚才最能打动人，我并不擅长撩人。我不是什么温柔的人，但是却打算为你做尽温柔事。</p><p>可阅读使我刻在骨子里的教养，不敢轻易的冒犯。我不敢说话太轻浮或者太撩，我怕你觉得我是不是对任何女生都这样，我觉得你是那种需要慢慢的靠近，慢慢的互相了解。可你一直被给互相一个真正认识的机会……</p><p>说这些，也不知道会不会给你带来压力。只是我真诚的希望咱们给互相一个机会，给一个喜欢你的男孩一个机会。</p><p>我觉得尽管我们是相亲认识的，但是我觉得那又怎么样，在茫茫人海里遇见你也是一种缘分，尽管相亲认识的很少有互相喜欢的，都是条件碰条件。但是我觉得我对你的感情也好、条件也好。我都能真诚，认真的对待你 ，在跟你那天见完面后，我就觉得：你永远是我的 Plan A。</p><p>我不给承诺，因为我是一个行动派。</p><p>我们可以先接触看看，希望我们下次见。</p><div style="text-align:center;"><p>山海袅娜，星河旖旎，人间所有的存在里……</p></div><p>月亮被嚼碎了变成了星星 你就藏在漫天的星光里</p><p>我看晚霞时不干任何事</p><p>当场眼睛看见时很美，</p><p>分享的给你的想法很美，</p><p>要是你在身旁便是绝美……</p><details class="hint-container details"><summary>V0.1</summary><div style="text-align:center;"><p>希望多年后的你，</p><p>打开这封信后，依然如此地认真。</p><p>如果我年轻一些，我想花更长的时间追你～</p></div><div style="text-align:right;"><p>2024-01-21 18:32:50 家</p></div><hr><p>亲爱的佳珍你好，</p><p><s>给你写这封信此前，想了非常多。但我知道，我必须摆脱自我感动以最理智、最真诚的心写下这封“无声告白”。这封信，我写了许久，反复斟酌以免给你带来压力或者其它，但又需要表达清楚。</s></p><p>给你写这封信此前，想了非常多。但我知道，我必须摆脱自我感动以最理智、最真诚的心写下这信。这封信，我写了许久，反复斟酌以免给你带来压力或者其它，但又需要表达清楚。</p><p><s>27年来，我从未知道失眠是什么，也不知道人为什么会失眠。从某一个中午，我遇见了一人。我半夜突然醒来，但不论如何都睡不着，大脑异常的清醒。原来，我失眠了。</s></p><p>我这十几天一直很不平静，<s>跟全球的学员不停的沟通和交流</s>。因为，我遇到了一个非常需要我全身心且谨慎、小心翼翼、尊重的一个女生。</p><p>她让我心动，<s>心跳不受控制的心动</s>。也让我“度日如年”，时刻等待着另一端回信。</p><p>她很懂礼貌，是唯一一个会把人送到门口的，也是我唯一在走出时，不停回头去看。</p><p>她和我见面时，同我一样紧张。我想看着她脸对话，但紧张使我不敢看太久。</p><p>她的每一次回复，我都非常开心，就像一个小孩收到了一件珍贵的礼物似的。导致，我无法抑制的发了很长很长的小作文。<s>——对，我干坏事了。我写了一个小作文，我的真诚在小作文下，化为泡影、转为负担。</s></p><p>她有点冷漠，我需要不停的找话题，不停的想跟她互相了解。<s>大家都</s>或许理性的大脑早已告诉我说：放弃吧、不用找话题顺其自然就行，<s>可他们并不知你的回复</s>。</p><p><s>我貌似没通过她给我的两个测试，一个月亮，一个关心。</s></p><p><s>我很可笑，像个小孩一样跑到五楼去拍月亮。我自己都想笑我自己，关心又过度关心像舔狗。</s></p><p><s>朋友都说我，全中国有多少工资能到 1万的，你一个月 3万+。</s></p><p>我的能力与经历，很少有人或事让我如此卑微或舔<s>，何故如此卑微</s>。但我和沈从文想法一致：在心爱的人面前，卑微算什么呢？</p><p><s>虽然，我没通过你的两个测试。</s></p><p><s>但我是懂浪漫的，我是有这个经济能力来浪漫的。</s></p><p><s>你喜欢浪漫、仪式感。但你知道么，我也喜欢浪漫。</s></p><p>我总觉得真诚才最能打动人，我并不擅长撩人。我不是什么温柔的人，但是却打算为你做尽温柔事。</p><p>可阅读使我刻在骨子里的教养，不敢轻易的冒犯。我不敢说话太轻浮或者太撩，我怕你觉得我是不是对任何女生都这样，<s>我是那种需要慢慢的接近你，会慢慢的浪漫。但你一直没有给我机会……</s> 我觉得你是那种需要慢慢的靠近，慢慢的互相了解。可你一直被给互相一个真正认识的机会……</p><p><s>见到你的那天晚上，我脑海就像放电影。我深刻知道了，这是一个我不用动脑就能宠爱的女生。我一瞬间想到我之前看到的短视频，一男的给心爱的女孩打造 12件定情信物。我也会如此，我会用我自己赚的钱，去为你打造 12件礼物。我会选择最好的伯爵旅拍的林云来拍摄等等，这一切都是我脑海不用设计就浮现的。</s></p><p>说这些，也不知道会不会给你带来压力。<s>不是逼你马上确定关系啥的，</s> 只是我真诚的希望咱们给互相一个机会，给一个喜欢你的男孩一个机会。</p><p>我觉得尽管我们是相亲认识的，但是我觉得那又怎么样，在茫茫人海里遇见你也是一种缘分，尽管相亲认识的很少有互相喜欢的，都是条件碰条件。但是我觉得我对你的感情也好、条件也好。我都能真诚，认真的对待你 ，在跟你那天见完面后，我就觉得：你永远是我的 Plan A。</p><p><s>毕竟其他人不确定更多，我一个人一步步事业走到这个地步，能力心性在这。还是你想找一个你喜欢，他不喜欢你呢？</s></p><p><s>这个男孩教学了很多学生和家长，人品不行的话不会做这么久的私教。私教很考验能力和人品的，我也有带小孩。如果我品行不正，家长不可能让我长期带。</s></p><p><s>这个男孩，遇到你之前就办理了一个护照。这个护照代表着，我想带我未来另一半，定期旅行。我要带她去浪漫之地，我也要会顾家。</s></p><p><s>这个男孩，傻傻的因为你的提问，写了小作文。</s></p><p><s>这个男孩，在你面前的所有心思都是不想擦身而过。</s></p><p>我不给承诺，因为我是一个行动派。</p><p><s>你点赞的两个朋友圈，都是我想让你看见我对你的心意。</s></p><p>我们可以先接触看看，希望我们下次见。</p><p><s>我们缺少交流和再次见面交流。</s></p><div style="text-align:center;"><p><s>如果我早点遇到你，那该多好！但那时候我没钱没事业。</s></p><p><s>此刻，真恰如其分，我有钱有事业，遇上你，我想拥有爱情。</s></p><p><s>我想带你浪漫，给你最好的婚礼和婚纱照。</s></p><p>复杂的世界，一个就好～</p></div></details><p>当场眼睛看见时很美，</p><p>分享的给你的想法很美，</p><p>要是你在身旁是绝美……</p><hr><p>见面计划：</p><ol><li><p>后天</p></li><li><p>媒婆约见面：阿姨跟媒婆说，之前安排相亲，对你闺女感觉特别好，人也特别善良。我孩子挺中意你家闺女的。阿姨说，但是你们做父母的还没回来嘛，没别的意思，让你们做父母的也了解一下。也是想跟你们介绍一下我的儿子，我儿子人各方面条件也还可以。不管是人品还是收入都还可以。我个人感觉两孩子挺搭的。也让两个孩子再见一面，之前了解也不太深，我们家孩子挺腼腆的，再相互了解了解。让他们自己聊，能成我们也都挺高兴的。</p></li><li><p>我要注意什么：</p><ol><li>见面第一句：这几天都没睡好，再看到你心情好了很多</li><li>礼物不能讲</li><li>送东西的不能提</li><li>可爱的女孩子都爱吃嘛，我就是想买点好吃的东西，能逗你开心；</li><li>不要文邹邹，大白话，不能小作文一样</li><li>称呼：康老师，</li><li>其实上次跟你说，跟你见面后我不想相亲了，这句话真不是夸张，有时候缘分就是这么奇妙，看到自己注定的那个人，可能那一眼就认定了。因为我也是个感性的人，我一直坚持的原因：是我想跟我喜欢的人在一起，我不想将就，所以我未来的世界不想失去你，我想陪伴你生活，和你去一起看世界美好的东西。</li></ol></li></ol><p>康老师晚安噢，希望你的梦里有我噢</p><p>佳珍，不管是开心的事情</p><p>我希望以后你开心的事情也能和我分享一下，我也能给你分享一下。哪天如果不开心，我也可以当你的垃圾桶，佳珍，晚安噢。</p><p>佳珍，在家不无聊吗，那你等我，五分钟</p><p>我到咯，出来吧</p><p>你不是无聊嘛，我带你去个地方，把无聊这个东西消除掉</p>`,38)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};